suppressPackageStartupMessages({library(Seurat); library(Matrix); library(harmony); library(data.table)})
base <- "/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/external_CAF_data"
out <- file.path(base, "integrated")
markers <- list(CAF=c("COL1A1","COL1A2","DCN","LUM","COL3A1","PDGFRA","PDGFRB","C7","CFD","COL6A1","COL6A2","COL6A3","FAP","ACTA2"), epithelial=c("EPCAM","KRT8","KRT18","KRT19","KRT7","KRT17","KRT14"), immune=c("PTPRC","CD3D","CD3E","MS4A1","CD79A","LYZ","FCER1G"), endothelial=c("PECAM1","VWF","KDR","EMCN"))
score <- function(z) { m <- GetAssayData(z, layer="counts"); for (nm in names(markers)) {g<-intersect(markers[[nm]],rownames(m)); z[[paste0(nm,"_score")]]<-if(length(g)>=2) Matrix::colMeans(m[g,,drop=FALSE]) else 0}; md<-z[[]]; z$CAF_candidate<-md$CAF_score>md$epithelial_score & md$CAF_score>md$immune_score & md$CAF_score>md$endothelial_score; z }
read10x <- function(g, sample, prefix) { d<-file.path(base,"processed",g); fs<-list.files(d, full.names=TRUE); m<-fs[grepl(paste0(prefix,"_matrix\\.mtx\\.gz$"),fs)]; b<-fs[grepl(paste0(prefix,"_barcodes\\.tsv\\.gz$"),fs)]; f<-fs[grepl(paste0(prefix,"_genes\\.tsv\\.gz$"),fs)]; z<-CreateSeuratObject(ReadMtx(m,b,f,feature.column=2), project=g, min.cells=0, min.features=0); z$dataset<-g; z$sample_id<-sample; z$tissue<-"BLCA_tumor"; z }
spec <- list(GSE130001=c("GSM3729178_sample1","GSM3729179_sample2"), GSE129845=c("GSM3723357_Sample1","GSM3723358_Sample2","GSM3723359_Sample3","GSM3723360_Sample4","GSM3723361_Sample5"))
new <- list(); audit <- list()
for (g in names(spec)) for (p in spec[[g]]) { z<-read10x(g,p,p); z<-score(z); ncf<-sum(z$CAF_candidate); audit[[length(audit)+1]]<-data.table(dataset=g,sample=p,n_total=ncol(z),n_CAF=ncf); if(ncf>0) new[[length(new)+1]]<-subset(z,subset=CAF_candidate); rm(z); gc() }
old <- readRDS(file.path(out,"GSE135337_GSE190888_CAF_Harmony_integrated.rds")); old <- JoinLayers(old); old <- subset(old, subset=dataset %in% c("GSE135337","GSE190888")); all <- Reduce(function(a,b) merge(a,b), c(list(old),new)); all<-JoinLayers(all); all<-NormalizeData(all,verbose=FALSE); all<-FindVariableFeatures(all,nfeatures=3000,verbose=FALSE); all<-ScaleData(all,features=VariableFeatures(all),verbose=FALSE); all<-RunPCA(all,features=VariableFeatures(all),npcs=30,verbose=FALSE); all<-RunHarmony(all,group.by.vars="dataset",reduction.use="pca",dims.use=1:30,assay.use="RNA",plot_convergence=FALSE); all<-FindNeighbors(all,reduction="harmony",dims=1:30,verbose=FALSE); all<-FindClusters(all,resolution=.4,verbose=FALSE); all<-RunUMAP(all,reduction="harmony",dims=1:30,verbose=FALSE); all$GDF15_score<-as.numeric(GetAssayData(all,layer="data")[intersect("GDF15",rownames(all)),]); all$GDF15_group<-ifelse(all$GDF15_score>0,"GDF15_detected","GDF15_not_detected"); fwrite(rbindlist(c(list(data.table(dataset="GSE135337+GSE190888",sample="existing_integrated",n_total=NA,n_CAF=ncol(old))),audit)),file.path(out,"CAF_specific_candidate_audit.csv")); fwrite(as.data.table(all[[]],keep.rownames="cell_id"),file.path(out,"CAF_specific_integrated_metadata.csv")); saveRDS(all,file.path(out,"GSE135337_GSE190888_GSE130001_GSE129845_CAF_Harmony_integrated.rds"),compress="xz"); writeLines(c("Integration completed",paste("cells",ncol(all)),paste("datasets",paste(unique(all$dataset),collapse=",")),paste("GDF15_detected",sum(all$GDF15_group=="GDF15_detected"))),file.path(out,"CAF_specific_RUN_STATUS.txt")); writeLines(capture.output(sessionInfo()),file.path(out,"CAF_specific_sessionInfo.txt"))
